/** Only exact single-address mappings enter the native case. Generic ranges
  * and masks keep their established independent matching/priority path.
  */
protected def validateNamedAddressCases(): Unit = {
  if (!elementsPerAddress.keys.exists(_.isInstanceOf[TypedLocalSingleMapping])) return
  val singles = elementsPerAddress.keys.toVector.collect {
    case named: TypedLocalSingleMapping => (named: AddressMapping, named.local.elab)
    // Typed elaboration values are Int-bounded; larger fixed addresses
    // cannot overlap a named address and retain their historical path.
    case fixed: SingleMapping if fixed.address.isValidInt => (fixed: AddressMapping, ElabInt.fromBigInt(fixed.address))
  }
  for (i <- singles.indices; j <- 0 until i
      if singles(i)._1.isInstanceOf[TypedLocalSingleMapping] || singles(j)._1.isInstanceOf[TypedLocalSingleMapping]) {
    if (!singles(i)._2.elabEq(singles(j)._2).isAlwaysFalse)
      throw new ParameterizedVerilogException("SPINAL-LOCALPARAM-BUS-ADDRESS-OVERLAP",
        "named case addresses must be disjoint over their complete admitted domains", None)
  }
}

// ElabIntSingleMapping intentionally remains a generic AddressMapping.

/** One named, compile-time address. Equivalent exact address functions retain
  * the factory's existing shared-address grouping and double-read checks.
  */
final class TypedLocalSingleMapping(val local: TypedLocalUInt,
    private[misc] val underlying: ElabIntSingleMapping) extends AddressMapping {
  override def hit(address: UInt): Bool = address === local.asUInt
  override def hit(address: BigInt): Boolean = underlying.hit(address)
  override def removeOffset(address: UInt): UInt = U(0)
  override def lowerBound: BigInt = underlying.lowerBound
  override def highestBound: BigInt = underlying.highestBound
  override def randomPick(): BigInt = underlying.randomPick()
  override def foreach(body: BigInt => Unit): Unit = underlying.foreach(body)
  override def withOffset(offset: BigInt): AddressMapping =
    if (offset == 0) this else underlying.withOffset(offset)
  override def equals(that: Any): Boolean = that match {
    case other: TypedLocalSingleMapping => underlying == other.underlying
    case _ => false
  }
  override def hashCode(): Int = underlying.hashCode()
  override def toString: String = s"Named address ${local.name}"
}
